use super::{tsrust_native_http::*,tsrust_native_futures as tasks};
use std::{sync::{Arc,Mutex,atomic::{AtomicUsize,Ordering}},time::Duration};
fn cors(lists:[&[&str];4],credentials:bool,age:Option<i64>)->Result<NativeMiddleware,Error>{NativeMiddleware::cors(Some(lists[0].iter().copied()),Some(lists[1].iter().copied()),Some(lists[2].iter().copied()),Some(lists[3].iter().copied()),Some(credentials),age)}
#[test]
fn source_policy_construction_validates_before_install_and_preserves_closed_defaults(){
 for index in 0..4{let mut lists:[&[&str];4]=[&[],&[],&[],&[]];lists[index]=&["*"];assert_eq!(cors(lists,true,None).err().unwrap().code,"options");}
 for lists in [[&["*","https://allowed.example"][..],&[],&[],&[]],[&["bad\r\norigin"][..],&[],&[],&[]],[&[],&["bad method"][..],&[],&[]],[&[],&[],&["bad header"][..],&[]],[&[],&[],&[],&["bad header"][..]]]{assert_eq!(cors(lists,false,None).err().unwrap().code,"options");}
 assert_eq!(cors([&[],&[],&[],&[]],false,Some(-1)).err().unwrap().code,"options");assert!(cors([&[],&[],&[],&[]],false,Some(0)).is_ok());assert!(cors([&[],&[],&[],&[]],false,Some(i64::MAX)).is_ok());
}
#[test]
fn contextual_policies_keep_path_order_body_owner_and_backend_response_metadata(){tasks::block_on(async{
 let trace=Arc::new(Mutex::new(Vec::new()));let entered=Arc::new(AtomicUsize::new(0));let mut router=Router::new();let seen=trace.clone();
 router.use_middleware(move|context,next|{let seen=seen.clone();Box::pin(async move{seen.lock().unwrap().push("before");context.header("x-before","one").unwrap();next.run(context).await;seen.lock().unwrap().push("after");context.header("x-after","two").unwrap();None})});
 router.use_many("/api/*",vec![cors([&["https://allowed.example"],&["POST"],&["x-input"],&["x-after"]],true,Some(0)).unwrap().into_context(),NativeMiddleware::secure_headers().into_context(),NativeMiddleware::compress().into_context()]).unwrap();let called=entered.clone();
 router.route("POST","/api/:name",move|context|{let called=called.clone();Box::pin(async move{called.fetch_add(1,Ordering::SeqCst);assert_eq!(context.field0.param("name").as_deref(),Some("echo"));let body=context.request_text().await.unwrap();context.header("content-length",&body.len().to_string()).unwrap();Some(context.text(body,None).unwrap())})}).unwrap();
 router.route("GET","/outside",|context|Box::pin(async move{Some(context.text("outside".into(),None).unwrap())})).unwrap();let server=router.listen("127.0.0.1:0").await.unwrap();let client=Client::with_transport_options(None,None,None,None,None,None,None,Some(true)).unwrap();let url=format!("http://{}",server.address());
 let expected="exclusive body é".repeat(32);let mut input=Request::new("POST",&format!("{url}/api/echo"),expected.clone()).unwrap();input.set_header("origin","https://allowed.example").unwrap();input.set_header("accept-encoding","gzip").unwrap();let response=tokio::time::timeout(Duration::from_secs(5),client.send(input)).await.unwrap().unwrap();
 assert_eq!(response.header("access-control-allow-origin").unwrap().as_deref(),Some("https://allowed.example"));assert_eq!(response.header("x-frame-options").unwrap().as_deref(),Some("SAMEORIGIN"));assert_eq!(response.header("x-before").unwrap().as_deref(),Some("one"));assert_eq!(response.header("x-after").unwrap().as_deref(),Some("two"));assert!(response.header("content-length").unwrap().is_none());assert_eq!(response.header("content-encoding").unwrap().as_deref(),Some("gzip"));let mut encoded=Vec::new();let mut body=response.body();while let Some(bytes)=body.next().await.unwrap(){encoded.extend(bytes);}let mut plain=String::new();use std::io::Read;flate2::read::GzDecoder::new(encoded.as_slice()).read_to_string(&mut plain).unwrap();assert_eq!(plain,expected);assert_eq!(*trace.lock().unwrap(),["before","after"]);
 let outside=client.send(Request::new("GET",&format!("{url}/outside"),String::new()).unwrap()).await.unwrap();assert!(outside.header("x-frame-options").unwrap().is_none());assert!(outside.header("access-control-allow-origin").unwrap().is_none());assert_eq!(outside.text_body().await.unwrap(),"outside");
 let mut input=Request::new("OPTIONS",&format!("{url}/api/echo"),String::new()).unwrap();input.set_header("origin","https://allowed.example").unwrap();input.set_header("access-control-request-method","POST").unwrap();let response=client.send(input).await.unwrap();assert_eq!(response.status(),200);assert_eq!(response.header("access-control-allow-credentials").unwrap().as_deref(),Some("true"));assert_eq!(entered.load(Ordering::SeqCst),1);tokio::time::timeout(Duration::from_secs(5),server.shutdown()).await.unwrap();
});}
#[test]
fn owned_app_policies_preserve_authored_headers_and_identity_wildcard_behavior(){tasks::block_on(async{
 let mut app=App::new();app.use_native(NativeMiddleware::secure_headers());app.use_native(NativeMiddleware::compress());app.use_native(cors([&["https://allowed.example"],&["GET"],&[],&[]],false,None).unwrap());
 app.route("GET","/",|_|async{let mut response=Response::text("backend response".repeat(32),500).unwrap();response.set_header("x-frame-options","DENY").unwrap();response}).unwrap();let server=app.listen("127.0.0.1:0").await.unwrap();let client=Client::with_transport_options(None,None,None,None,None,None,None,Some(true)).unwrap();let mut request=Request::new("GET",&format!("http://{}/",server.address()),String::new()).unwrap();request.set_header("origin","https://allowed.example").unwrap();request.set_header("accept-encoding","*").unwrap();let response=client.send(request).await.unwrap();assert_eq!(response.status(),500);assert_eq!(response.header("x-frame-options").unwrap().as_deref(),Some("DENY"));assert_eq!(response.header("x-content-type-options").unwrap().as_deref(),Some("nosniff"));assert_eq!(response.header("referrer-policy").unwrap().as_deref(),Some("no-referrer"));assert!(response.header("content-encoding").unwrap().is_none());assert_eq!(response.text_body().await.unwrap(),"backend response".repeat(32));tokio::time::timeout(Duration::from_secs(5),server.shutdown()).await.unwrap();
});}
#[test]
fn policy_wrappers_preserve_request_scope_cleanup_on_disconnect_and_shutdown(){
 use std::io::Write;struct Guard(Arc<AtomicUsize>);impl Drop for Guard{fn drop(&mut self){self.0.fetch_add(1,Ordering::SeqCst);}}
 for disconnect in [true,false]{let dropped=Arc::new(AtomicUsize::new(0));let seen=dropped.clone();tasks::block_on(async move{
  let entered=Arc::new(tokio::sync::Notify::new());let notify=entered.clone();let mut app=App::new();app.configure([1048576,128,128,30000,50,5000,0]).unwrap();app.use_native(NativeMiddleware::cors_default());app.use_native(NativeMiddleware::secure_headers());app.use_native(NativeMiddleware::compress());
  app.route("GET","/pending",move |_|{let guard=Guard(seen.clone());let notify=notify.clone();async move{let _child=tasks::start(async move{let _guard=guard;notify.notify_one();std::future::pending::<()>().await;Ok::<_,tasks::Failure<()>>(())});std::future::pending::<Response>().await}}).unwrap();let server=app.listen("127.0.0.1:0").await.unwrap();let address=server.address();let mut socket=std::net::TcpStream::connect(&address).unwrap();socket.write_all(b"GET /pending HTTP/1.1\r\nHost: localhost\r\nAccept-Encoding: gzip\r\n\r\n").unwrap();tokio::time::timeout(Duration::from_secs(5),entered.notified()).await.unwrap();
  if disconnect{drop(socket);tokio::time::timeout(Duration::from_secs(5),async{while seen.load(Ordering::SeqCst)==0{tokio::task::yield_now().await;}}).await.unwrap();tokio::time::timeout(Duration::from_secs(5),server.shutdown()).await.unwrap();}else{tokio::time::timeout(Duration::from_secs(5),server.shutdown()).await.unwrap();drop(socket);}assert_eq!(seen.load(Ordering::SeqCst),1);assert!(tokio::net::TcpListener::bind(address).await.is_ok());
 });assert_eq!(dropped.load(Ordering::SeqCst),1);}
}
